{
  "name": "整数编号任务规则",
  "name_en": "Integer ID Rule",
  "manufacturer": "",
  "description": "这是一个用于集群计算工作流的规则对象，而非物理实验设备。它按整数任务编号生成、发布和跟踪任务，常用于显微成像数据分析或配方型数据处理流程中的任务调度、完成状态管理与超时重试控制。",
  "description_en": "This is a software workflow rule object rather than a physical laboratory device. It generates, releases, and tracks tasks indexed by integer IDs, and is used in cluster-based microscopy data analysis or recipe-style processing workflows for task scheduling, completion tracking, and timeout/retry handling.",
  "actions": [
    {
      "action_name": "auto-mark_release_complete",
      "description": "标记该规则的任务释放已完成，并可定义最终任务数量。",
      "description_en": "Mark task release for this rule as complete, and optionally define the final number of tasks."
    },
    {
      "action_name": "auto-make_range_available",
      "description": "将指定编号范围内的任务设为可用。",
      "description_en": "Make a specified range of task IDs available."
    },
    {
      "action_name": "auto-bid",
      "description": "对可分配任务发起竞标并返回匹配的任务。",
      "description_en": "Submit a bid for available tasks and return any matched tasks."
    },
    {
      "action_name": "auto-mark_complete",
      "description": "标记一组任务为已完成或失败。",
      "description_en": "Mark a set of tasks as completed or failed."
    },
    {
      "action_name": "auto-inactivate",
      "description": "将该规则设为非活动状态，使其不再发布任务广告。",
      "description_en": "Set the rule inactive so it no longer advertises tasks."
    },
    {
      "action_name": "auto-info",
      "description": "获取该规则的任务数量与运行状态信息。",
      "description_en": "Get task counts and runtime status information for this rule."
    },
    {
      "action_name": "auto-poll_timeouts",
      "description": "轮询任务超时状态并更新相关记录。",
      "description_en": "Poll for task timeouts and update related status records."
    }
  ],
  "tag_hints": [
    "task scheduling",
    "workflow orchestration",
    "cluster computing",
    "microscopy data analysis",
    "distributed processing",
    "timeout and retry management",
    "rule-based task generation"
  ]
}

